const initialEntities: Record<string, string> = {
  Osk: "nim",
  Fen: "nim",
};

function copyState(state: WorldStateHandle): WorldStateHandle {
  return { entities: { ...state.entities } };
}

function invalidTransition(operationDisplayName: string): {
  success: false;
  error: string;
} {
  return {
    success: false,
    error: `Operation ${operationDisplayName} cannot be applied in the current state`,
  };
}

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { entities: { ...initialEntities } };
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    const next = copyState(state);

    if (operationDisplayName === "advanceOskFen") {
      if (state.entities.Osk !== "nim" || state.entities.Fen !== "nim") {
        return invalidTransition(operationDisplayName);
      }

      next.entities.Osk = "pex";
      next.entities.Fen = "pex";
      return { success: true, newState: next };
    }

    if (operationDisplayName === "advanceOsk") {
      if (state.entities.Osk !== "nim") {
        return invalidTransition(operationDisplayName);
      }

      next.entities.Osk = "pex";
      return { success: true, newState: next };
    }

    if (operationDisplayName === "advanceFen") {
      if (state.entities.Fen !== "nim") {
        return invalidTransition(operationDisplayName);
      }

      next.entities.Fen = "pex";
      return { success: true, newState: next };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state.entities };
  },
};
